@media (prefers-reduced-motion: no-preference) {
  .yt-thanks-modal.is-visible .yt-thanks-dialog {
    animation: ytThanksDialogIn 180ms ease-out;
  }

  @keyframes ytThanksDialogIn {
    from {
      opacity: 0;
      transform: translateY(6px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

/* =========================================================
 * 首页：链接
 * ========================================================= */

.yt-links {
  padding: 0 var(--page-padding) 28px;
}

.yt-home-heading {
  margin-bottom: 5px;
  color: #0f0f0f;
  font-size: 17px;
  font-weight: 650;
  line-height: 1.25;
}

.yt-link-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.yt-link-item {
  min-height: 51px;
  display: flex;
  align-items: center;
  gap: 15px;
  cursor: default;
}

.yt-link-icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;

  color: #0f0f0f;
  font-size: 25px;
  font-weight: 700;
  line-height: 1;
}

.yt-link-icon img {
  width: 30px;
  height: 30px;
  max-width: none;
  display: block;
  object-fit: contain;

  border: 0;
  border-radius: 0;
  background: transparent;
}

.yt-link-icon svg {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  display: block;
  overflow: visible;
}

.yt-link-body {
  min-width: 0;
  flex: 1;
}

.yt-link-name {
  color: #0f0f0f;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.yt-link-url {
  width: fit-content;
  max-width: 100%;
  margin-top: 4px;
  color: #045ED4;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
  overflow-wrap: anywhere;
  cursor: pointer;
}

/* =========================================================
 * 首页：更多信息
 * ========================================================= */

.yt-more-info {
  --info-art-width: 50px; /* 素材图显示宽度 */
  --info-art-x: -16px;     /* 水平：负数向左，正数向右 */
  --info-art-y: 6px;      /* 垂直：负数向上，正数向下 */

  --info-font-size: 13px;
  --info-font-weight: 550;
  --info-line-height: 1.35;
  --info-row-gap:  21px;
  --info-row-height: 20px;

  padding: 0 var(--page-padding) 32px;
}

.yt-info-art {
  width: var(--info-art-width);
  height: auto;
  max-width: none;
  flex: 0 0 var(--info-art-width);
  display: block;
  object-fit: contain;
  transform: translate(
    var(--info-art-x),
    var(--info-art-y)
  );
}

/* 素材图和右侧文字并排 */
.yt-info-content {
  display: flex;
  align-items: flex-start;
  gap: -10px; /* 素材图本身已经包含留白，所以这里不再增加间距 */
}

/* 右侧文字列表 */

.yt-info-list {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--info-row-gap);

  margin-left: -3.5px;
  margin-top: 12px; /* 正数整体下移，负数整体上移 */
}

.yt-info-item {
  min-height: var(--info-row-height);
  display: flex;
  align-items: center;
}

.yt-info-text {
  min-width: 0;
  flex: 1;
  color: #0f0f0f;
  font-size: var(--info-font-size);
  font-weight: var(--info-font-weight);
  line-height: var(--info-line-height);
  overflow-wrap: anywhere;
}

.yt-info-text.is-link {
  color: #045ED4;
}

/* =========================================================
 * 视频排序
 * ========================================================= */

.yt-sort {
  padding: 16px var(--page-padding) 9px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.yt-sort-button {
  height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  color: #0f0f0f;
  background: #f2f2f1;
  font-size: 12px;
  font-weight: 590;
  white-space: nowrap;
  cursor: pointer;
}

.yt-sort-button.is-active {
  color: #f5f5f5;
  background: #0f0f0f;
}

/* =========================================================
 * 视频列表
 * ========================================================= */

.yt-videos {
  width: 100%;
  padding: 2px var(--page-padding) 22px;
}

.yt-videos::-webkit-scrollbar {
  display: none;
}

.yt-video {
  width: 100%;
  min-height: 115px;
  display: flex;
  align-items: flex-start;
  gap: 19px;
  padding: 10px 0;
  cursor: pointer;
}

.yt-video-thumb {
  position: relative;
  width: 160px;
  height: 95px;
  flex: 0 0 160px;
  overflow: hidden;
  border-radius: 8px;
  background: #ededed;
}

.yt-video-thumb img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

.yt-duration {
  position: absolute;
  right: 6px;
  bottom: 6px;
  min-width: 38px;
  height: 21px;
  padding: 0 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  color: #ffffff;
  background: rgba(25, 25, 25, 0.55);
  font-size: 11px;
  font-weight: 650;
  line-height: 1;
  white-space: nowrap;
}

.yt-video-info {
  min-width: 0;
  min-height: 95px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.yt-video-title-row {
  display: flex;
  align-items: flex-start;
  gap: 5px;
}

.yt-video-title {
  min-width: 0;
  flex: 1;
  color: #0f0f0f;
  font-size: 14px;
  font-weight: 550;
  line-height: 1.4;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.yt-video-menu {
  width: 30px;
  height: 25px;
  flex: 0 0 30px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 2px;
  border: 0;
  color: #303030;
  background: transparent;
  cursor: pointer;
}

.yt-video-menu span {
  width: 3px;
  height: 3px;
  flex: 0 0 3px;
  display: block;
  border-radius: 50%;
  background: currentColor;
}

.yt-video-meta {
  color: #606060;
  font-size: 12px;
  font-weight: 450;
  line-height: 1.4;
}

.yt-empty {
  padding: 46px 20px;
  color: #606060;
  font-size: 14px;
  text-align: center;
}

/* =========================================================
 * 底部导航
 * ========================================================= */

.yt-bottom-bar {
  position: relative;
  width: 100%;
  overflow: hidden;
  line-height: 0;
  background: #ffffff;
}

.yt-bottom-bar-image {
  width: 100%;
  height: auto;
  display: block;
}

.yt-bottom-label {
  position: absolute;
  z-index: 2;
  top: 56%;
  color: #0f0f0f;
  font-size: 9px;
  font-weight: 500;
  line-height: 1.1;
  white-space: nowrap;
  text-align: center;
  pointer-events: none;
  transform: translateX(-50%);
}

.yt-bottom-label-home {
  left: 10%;
}

.yt-bottom-label-shorts {
  left: 30%;
}

.yt-bottom-label-subscribe {
  left: 70%;
}

.yt-bottom-label-me {
  left: 90%;
}

.yt-bottom-avatar {
  position: absolute;
  z-index: 2;
  top: 7%;
  left: 90%;
  width: 26px;
  height: 26px;
  overflow: hidden;
  border-radius: 50%;
  background: #ededed;
  transform: translateX(-50%);
}

.yt-bottom-avatar img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

.yt-bottom-space {
  height: 0px;
}

/* =========================================================
 * 交互反馈
 * ========================================================= */

@media (prefers-reduced-motion: no-preference) {
.yt-tab,
.yt-sort-button,
.yt-video,
.yt-link-url {
    transition:
      color 120ms ease,
      background-color 120ms ease,
      transform 120ms ease;
  }

.yt-sort-button:active,
.yt-video:active {
  transform: scale(0.985);
}

.yt-link-url:active {
  opacity: 0.65;
}
}

/* 首页板块标题：统一粗细 */
.yt-section-title,
.yt-thanks-heading,
.yt-home-heading {
  font-weight: 650;
}

/* =========================================================
 * 弹窗上半部分背景图
 * ========================================================= */

.yt-thanks-modal {
  --thanks-header-image:
    url("https://s3.bmp.ovh/2026/09/14/UbVPOSEQ.jpg");

  --thanks-header-image-opacity: 0.87; /* ◀ 图片整体浓淡：0～1 */
  --thanks-header-image-position: center 50%; /* ◀ 图片取景位置 */

  --thanks-header-fade-start: 40%; /* ◀ 从哪里开始向下变淡 */
  --thanks-header-bottom: 18px;    /* ◀ 名字下方的背景区域留白 */
}

/* 顶部留白转交给 header，背景才能从卡片顶端开始 */
.yt-thanks-dialog {
  padding-top: 0;
}

/* 宽度扩展到卡片左右边缘 */
.yt-thanks-header {
  position: relative;
  isolation: isolate;

  width: calc(100% + 48px);
  flex-shrink: 0;

  padding:
    var(--thanks-card-padding-top)
    24px
    var(--thanks-header-bottom);

  display: flex;
  flex-direction: column;
  align-items: center;
}

/* 背景图层：不参与排版，不影响头像与翅膀位置 */

.yt-thanks-header::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;

  background-image: var(--thanks-header-image);
  background-size: cover;
  background-position: var(--thanks-header-image-position);
  background-repeat: no-repeat;
  opacity: var(--thanks-header-image-opacity);

  -webkit-mask-image: linear-gradient(
    to bottom,
    #000 0%,
    #000 var(--thanks-header-fade-start),
    transparent 100%
  );

  mask-image: linear-gradient(
    to bottom,
    #000 0%,
    #000 var(--thanks-header-fade-start),
    transparent 100%
  );

  pointer-events: none;
}

/* 背景区下面才是感谢语 */
.yt-thanks-quote {
  flex-shrink: 0;
  margin-top: 0; /* ◀ 感谢语区与上半部分的额外间距 */
}

.yt-thanks-dialog:focus {
  outline: none;
}

/* =========================================================
 * 视频区：故事线分组
 * 按钮外观沿用现有 yt-sort-button
 * ========================================================= */

/* 排序和故事线共用一排，按钮多时左右滑动 */
.yt-sort {
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-x pan-y;
}

.yt-sort::-webkit-scrollbar {
  display: none;
}

.yt-sort-button {
  flex: 0 0 auto;
}

/* =========================================================
 * 帖子
 * ========================================================= */

.yt-posts {
  --post-lines: 6;             /* 收起时最多显示几行 */
  --post-body-size: 15px;      /* 正文字号 */
  --post-body-weight: 550;     /* 正文字重 */
  --post-body-line-height: 1.45;
  --post-avatar-size: 38px;
  --post-more-size: 12px;

  padding: 0 var(--page-padding) 24px;
  --post-first-gap: 10px; /* 排序栏下面，第一条帖子的顶部留白 */
}

.yt-posts > .yt-post:first-child {
  padding-top: var(--post-first-gap);
}

.yt-post {
  padding: 19px 0 18px;
  border-bottom: 1px solid var(--page-line);
}

.yt-post:last-child {
  border-bottom: 0;
}

/* 置顶标记 */
.yt-post-pin {
  margin-bottom: 11px;
  color: #606060;
  font-size: 11px;
  font-weight: 550;
  line-height: 1.4;
}

/* 头像、名字、时间、菜单 */
.yt-post-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.yt-post-avatar {
  width: var(--post-avatar-size);
  height: var(--post-avatar-size);
  flex: 0 0 var(--post-avatar-size);
  overflow: hidden;
  border-radius: 50%;
  background: #ededed;
}

.yt-post-avatar img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.yt-post-identity {
  flex: 1;
  min-width: 0;
}

.yt-post-author {
  color: #0f0f0f;
  font-size: 13px;
  font-weight: 580;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.yt-post-time {
  margin-top: 3px;
  color: #606060;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
}

.yt-post-menu-wrap {
  position: relative;
  align-self: flex-start;
}

.yt-post-menu {
  width: 28px;
  height: 34px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border: 0;
  background: transparent;
  color: #0f0f0f;
  cursor: pointer;
}

.yt-post-menu span {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
}

.yt-post-menu-panel {
  position: absolute;
  top: 35px;
  right: 0;
  z-index: 5;
  min-width: 112px;
  padding: 5px;
  border: 1px solid #eeeeee;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 4px 16px rgb(0 0 0 / 10%);
}

.yt-post-menu-panel button {
  width: 100%;
  padding: 10px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #0f0f0f;
  font-size: 12px;
  text-align: left;
  cursor: pointer;
}

/* 正文：保留配置里的换行 */
.yt-post-body-wrap {
  position: relative;
  margin-top: 17px;
}

.yt-post-body {
  color: #0f0f0f;
  font-size: var(--post-body-size);
  font-weight: var(--post-body-weight);
  line-height: var(--post-body-line-height);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* 正文展开按钮：跟随文字排版 */
.yt-post-more,
.yt-post-more.is-expanded {
  position: static;
  display: inline;

  margin: 0 0 0 4px; /* ◀ 按钮与前面文字的距离 */
  padding: 0;
  border: 0;

  color: #606060;
  background: transparent;

  font-family: inherit;
  font-size: var(--post-more-size, 13px); /* ◀ 了解详情／收起共用字号 */
  font-weight: 650;
  line-height: inherit;
  vertical-align: baseline;
  white-space: nowrap;

  cursor: pointer;
}

/* 可选的开场白入口 */
.yt-post-story {
  display: block;
  margin-top: 12px;
  padding: 0;
  border: 0;
  color: #045ed4;
  background: transparent;
  font-size: 12px;
  font-weight: 550;
  line-height: 1.5;
  cursor: pointer;
}

/* 底部操作行 */
.yt-post-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 17px;
}

.yt-post-action {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0;
  border: 0;
  color: #0f0f0f;
  background: transparent;
  font-size: 13px;
  font-weight: 650;
  line-height: 1;
  cursor: pointer;
}

.yt-post-action svg {
  width: 24px;
  height: 24px;
  display: block;
  flex-shrink: 0;
}

.yt-post-action--vote svg {
  width: 33px;
  height: 33px;
}

.yt-post-action--dislike svg {
  transform: rotate(180deg);
}

.yt-post-action-spacer {
  flex: 1;
}

/* 评论区 */
.yt-post-comments {
  margin-top: 12px;
  padding: 12px;
  border-radius: 10px;
  background: #f6f6f6;
}

.yt-post-comment + .yt-post-comment {
  margin-top: 13px;
  padding-top: 13px;
  border-top: 1px solid #e5e5e5;
}

.yt-post-comment-author {
  color: #0f0f0f;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.4;
}

.yt-post-comment-body {
  margin-top: 4px;
  color: #404040;
  font-size: 12px;
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.yt-post-comment-empty,
.yt-post-status {
  color: #606060;
  font-size: 11px;
  line-height: 1.5;
}

.yt-post-status:not(:empty) {
  margin-top: 8px;
}

.yt-posts [hidden] {
  display: none !important;
}

.yt-post button:focus-visible {
  outline: 2px solid #045ed4;
  outline-offset: 3px;
}

.yt-post-menu-panel button:hover {
  background: #f2f2f2;
}
/* =========================================================
 * 帖子操作行：集中调节区
 * ========================================================= */

.yt-posts {
  /* 整排操作按钮与正文的距离 */
  --post-actions-top: 17px;

  /* 操作按钮之间的基础间距 */
  --post-actions-gap: 16px;

  /* 图标与它旁边数字的距离 */
  --post-icon-count-gap: 6px;

  /* 点赞／踩 */
  --post-vote-size: 24px;

  /* 转发 */
  --post-share-size: 24px;
  --post-share-x: -14px;       /* 负数向左，正数向右 */
  --post-share-y: 0px;       /* 负数向上，正数向下 */

  /* 评论 */
  --post-comment-size: 24px;
  --post-comment-x: -14px;
  --post-comment-y: 0px;

  /* 转发与评论之间的额外间距
   * 叠加在 actions-gap 上；负数缩小，正数增大。
   */
  --post-share-comment-extra-gap: 3px;

  /* 右上角三个圆点 */
  --post-menu-dot-size: 4px; /* 越大越粗 */
  --post-menu-dot-gap: 2px;  /* 圆点边缘之间的距离 */
  --post-menu-x: 0px;
  --post-menu-y: 0px;
}

/* 整排操作区 */
.yt-post-actions {
  margin-top: var(--post-actions-top);
  gap: var(--post-actions-gap);
}

.yt-post-action {
  gap: var(--post-icon-count-gap);
}

/* 点赞和踩的图标尺寸 */
.yt-post-action--vote svg {
  width: var(--post-vote-size);
  height: var(--post-vote-size);
}

/* 转发：尺寸和图标位置 */
.yt-post-action--share svg {
  width: var(--post-share-size);
  height: var(--post-share-size);

  transform: translate(
    var(--post-share-x),
    var(--post-share-y)
  );
}

/* 评论：与转发之间的额外距离 */
.yt-post-action--comment {
  margin-left: var(--post-share-comment-extra-gap);
}

/* 评论：尺寸和图标位置 */
.yt-post-action--comment svg {
  width: var(--post-comment-size);
  height: var(--post-comment-size);

  transform: translate(
    var(--post-comment-x),
    var(--post-comment-y)
  );
}

/* 右上角三个圆点 */
.yt-post-menu {
  gap: var(--post-menu-dot-gap);

  transform: translate(
    var(--post-menu-x),
    var(--post-menu-y)
  );
}

.yt-post-menu span {
  width: var(--post-menu-dot-size);
  height: var(--post-menu-dot-size);
  flex-shrink: 0;
}

/* 只移动评论数字，保留评论 SVG 原有的位置 */
.yt-post-action--comment > span {
  transform: translateX(-10px);
}

/* 帖子配图 */
.yt-post-images {
  display: flex;
  flex-direction: column;
  gap: 10px;       /* 多张图片之间的距离 */
  margin-top: 14px; /* 图片与正文的距离 */
}

.yt-post-image {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  background: #f2f2f2;
}

/* 置顶标记：图标 + 文字 */
.yt-post-pin {
  display: flex;
  align-items: center;
  gap: 5px; /* ◀ 图标与文字的距离 */
}

.yt-post-pin svg {
  width: 11px;  /* ◀ 图标宽度 */
  height: 11px; /* ◀ 图标高度 */
  flex-shrink: 0;
  display: block;
}

/* =========================================================
 * 播放列表
 * ========================================================= */

.yt-pl-root {
  --pl-cover-width: 139px;
  --pl-cover-radius: 8px;
  --pl-list-gap: 24px;

  width: 100%;
  padding: 23px var(--page-padding) 28px;
}

.yt-pl-list {
  display: flex;
  flex-direction: column;
  gap: var(--pl-list-gap);
}

.yt-pl-card {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 17px;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
