  padding-top: 8px;
  isolation: isolate;
}

.yt-pl-stack::before,
.yt-pl-stack::after {
  content: "";
  position: absolute;
  height: 16px;
  border-radius: 7px 7px 0 0;
}

.yt-pl-stack::before {
  top: 0;
  left: 12px;
  right: 12px;
  background: var(--pl-back, #eeece8);
}

.yt-pl-stack::after {
  top: 4px;
  left: 6px;
  right: 6px;
  background: var(--pl-front, #d8d2c9);
}

.yt-pl-cover {
  position: relative;
  z-index: 1;
  width: 100%;
  aspect-ratio: 1.48;
  overflow: hidden;
  border-radius: var(--pl-cover-radius);
  background: var(--pl-soft, #eeece8);
}

.yt-pl-cover img,
.yt-pl-hero-cover img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

.yt-pl-number {
  position: absolute;
  top: 4px;
  left: 13px;
