  padding: 4px 8px;
  border-radius: 999px;
  color: #ffffff;
  background: rgba(25, 25, 25, 0.62);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.yt-pl-info {
  min-width: 0;
  flex: 1;
}

.yt-pl-title {
