/* ===== YouTube 暗号：故事线 + 上次点击的视频 ===== */

/*
 * 与播客使用不同的存储名称。
 * 频道 handle 不同，记录也分开。
 */
var YOUTUBE_BOOKMARK_KEY =
  "rabbit_youtube_bookmark_v1:" +
  String(cfg.handle || cfg.name || "default");

function readYouTubeBookmark() {
  try {
    var raw = sessionStorage.getItem(YOUTUBE_BOOKMARK_KEY);
    var value = raw ? JSON.parse(raw) : null;

    return value && typeof value === "object"
      ? value
      : null;
  } catch (error) {
    return null;
  }
}

function writeYouTubeBookmark(value) {
  try {
    if (value) {
      sessionStorage.setItem(
        YOUTUBE_BOOKMARK_KEY,
        JSON.stringify(value)
      );
    } else {
      sessionStorage.removeItem(YOUTUBE_BOOKMARK_KEY);
    }
  } catch (error) {
    /* 存储不可用时，仍然允许跳转 */
  }
}

var youtubeReturnBookmark = readYouTubeBookmark();
var youtubeBookmarkJumpBusy = false;

/* 读取分组配置，忽略空标识和重复标识 */
var videoGroups = [];

if (Array.isArray(cfg.videoGroups)) {
  cfg.videoGroups.forEach(function (group) {
    if (
      !group ||
      typeof group.id !== "string" ||
      !group.id.trim()
    ) {
      return;
    }

    var exists = videoGroups.some(function (item) {
      return item.id === group.id;
    });

    if (!exists) {
      videoGroups.push({
        id: group.id,
        label: group.label || group.id
      });
    }
  });
}
/*
 * 视频在配置区里的排列顺序，就是开场白顺序。
 *
 * 第一条视频对应 swipe 1，
 * 第二条视频对应 swipe 2，
 * 第三条视频对应 swipe 3……
 *
 * 用户不需要手动填写编号。
 */
var configuredVideos = Array.isArray(cfg.videos)
  ? cfg.videos
  : [];

configuredVideos.forEach(function (video, index) {
  if (!video || typeof video !== "object") {
    return;
  }

  /*
   * 保存原始排列位置：
   * 0 表示第一条视频，1 表示第二条视频。
   */
  video._youtubeListIndex = index;

  /*
   * YouTube 页面通常占用 swipe 0，
   * 因此视频开场白从 swipe 1 开始。
   */
  video.swipe = index + 1;
});

var state = {
  tab: cfg.defaultTab || "home",
  sort: cfg.defaultSort === "oldest" ? "oldest" : "latest",
  videoGroup: ""
};
if (
  cfg.playlistEnabled === false &&
  state.tab === "shorts"
) {
  state.tab = "home";
}

/* 用 swipe 和标题识别上次点击的视频 */
function matchesYouTubeBookmark(video, bookmark) {
  return !!(
    video &&
    bookmark &&
    String(video.swipe) === String(bookmark.swipe) &&
    String(video.title || "") === String(bookmark.title || "")
  );
}

if (youtubeReturnBookmark) {
  var savedVideo = (Array.isArray(cfg.videos) ? cfg.videos : [])
    .find(function (video) {
      return (
        video.tab === "videos" &&
        matchesYouTubeBookmark(video, youtubeReturnBookmark)
      );
    });

  var hasVideoTab = (cfg.tabs || []).some(function (tab) {
    return tab.id === "videos";
  });

  if (savedVideo && hasVideoTab) {
    state.tab = "videos";

    state.sort = youtubeReturnBookmark.sort === "oldest"
      ? "oldest"
      : "latest";

    var savedGroup = youtubeReturnBookmark.videoGroup;

    /*
     * 只有分组仍然存在、且目标视频仍属于这一组时，
     * 才恢复故事线筛选。
     */
    var groupStillValid =
      typeof savedGroup === "string" &&
      savedGroup !== "" &&
      savedVideo.group === savedGroup &&
      videoGroups.some(function (group) {
        return group.id === savedGroup;
      });

    state.videoGroup = groupStillValid ? savedGroup : "";
  } else {
    /* 原视频已删除或改名时，正常打开默认页面 */
    youtubeReturnBookmark = null;
  }
}


function byId(id) {
