  /* =======================================================
   * iOS 风格连续曲率圆角
   * ======================================================= */

  function toRadians(degrees) {
    return degrees * Math.PI / 180;
  }

  function createSquirclePath(
    width,
    height,
    cornerRadius,
    cornerSmoothing
  ) {
    var maxRadius =
      Math.min(width, height) / 2;

    cornerRadius =
      Math.min(
        Math.max(cornerRadius, 0),
        maxRadius
      );

    if (cornerRadius <= 0) {
      return (
        "M0 0" +
        "L" + width + " 0" +
        "L" + width + " " + height +
        "L0 " + height +
        "Z"
      );
    }

    var budget =
      maxRadius;

    var maxSmoothing =
      budget / cornerRadius - 1;

    if (maxSmoothing < 0.001) {
      return (
        "M" + cornerRadius + " 0" +
        "L" + (width - cornerRadius) + " 0" +
        "A" + cornerRadius + " " + cornerRadius +
          " 0 0 1 " + width + " " + cornerRadius +
        "L" + width + " " + (height - cornerRadius) +
        "A" + cornerRadius + " " + cornerRadius +
          " 0 0 1 " + (width - cornerRadius) + " " + height +
        "L" + cornerRadius + " " + height +
        "A" + cornerRadius + " " + cornerRadius +
          " 0 0 1 0 " + (height - cornerRadius) +
        "L0 " + cornerRadius +
        "A" + cornerRadius + " " + cornerRadius +
          " 0 0 1 " + cornerRadius + " 0Z"
      );
    }

    cornerSmoothing =
      Math.min(
        Math.max(cornerSmoothing, 0),
        maxSmoothing
      );

    var p =
      Math.min(
        (1 + cornerSmoothing) *
        cornerRadius,
        budget
      );

    var arcMeasure =
      90 * (1 - cornerSmoothing);

    var arc =
      Math.sin(
        toRadians(arcMeasure) / 2
      ) *
      cornerRadius *
      Math.sqrt(2);

    var angleAlpha =
      (90 - arcMeasure) / 2;

    var p3ToP4Distance =
      cornerRadius *
      Math.tan(
        toRadians(angleAlpha) / 2
      );

    var angleBeta =
      45 * cornerSmoothing;

    var c =
      p3ToP4Distance *
      Math.cos(
        toRadians(angleBeta)
      );

    var d =
      c *
      Math.tan(
        toRadians(angleBeta)
      );

    var b =
      (p - arc - c - d) / 3;

    var a =
      2 * b;

    return (
      "M " + (width - p) + " 0 " +

      "C " +
        (width - (p - a)) + " 0 " +
        (width - (p - a - b)) + " 0 " +
        (width - (p - a - b - c)) + " " + d + " " +

      "a " +
        cornerRadius + " " + cornerRadius +
        " 0 0 1 " + arc + " " + arc + " " +

      "C " +
        width + " " + (p - a - b) + " " +
        width + " " + (p - a) + " " +
        width + " " + p + " " +

      "L " +
        width + " " + (height - p) + " " +

      "C " +
        width + " " + (height - (p - a)) + " " +
        width + " " + (height - (p - a - b)) + " " +
        (width - d) + " " +
          (height - (p - a - b - c)) + " " +

      "a " +
        cornerRadius + " " + cornerRadius +
        " 0 0 1 -" + arc + " " + arc + " " +

      "C " +
        (width - (p - a - b)) + " " + height + " " +
        (width - (p - a)) + " " + height + " " +
        (width - p) + " " + height + " " +

      "L " +
        p + " " + height + " " +

      "C " +
        (p - a) + " " + height + " " +
        (p - a - b) + " " + height + " " +
        (p - a - b - c) + " " + (height - d) + " " +

      "a " +
        cornerRadius + " " + cornerRadius +
        " 0 0 1 -" + arc + " -" + arc + " " +

      "C 0 " +
        (height - (p - a - b)) + " " +
        "0 " + (height - (p - a)) + " " +
        "0 " + (height - p) + " " +

      "L 0 " +
        p + " " +

      "C 0 " +
        (p - a) + " " +
        "0 " + (p - a - b) + " " +
        d + " " + (p - a - b - c) + " " +

      "a " +
        cornerRadius + " " + cornerRadius +
        " 0 0 1 " + arc + " -" + arc + " " +

      "C " +
        (p - a - b) + " 0 " +
        (p - a) + " 0 " +
        p + " 0 Z"
    );
  }

  function applySquircle(element) {
    if (!element) {
      return;
    }

    /*
     * offsetWidth/offsetHeight 不包含 yt-page 的 transform 缩放，
     * 因此始终按 440px 设计尺寸生成 Mask。
     */
    var width =
      Math.round(
        element.offsetWidth
      );

    var height =
      Math.round(
        element.offsetHeight
      );

    if (!width || !height) {
      return;
    }

    var radius =
      parseFloat(
        element.getAttribute(
          "data-radius"
        )
      );

    var smoothing =
      parseFloat(
        element.getAttribute(
          "data-smooth"
        )
      );

    if (!Number.isFinite(radius)) {
      radius = 18;
    }

    if (!Number.isFinite(smoothing)) {
      smoothing = 0.6;
    }

    var path =
      createSquirclePath(
        width,
        height,
        radius,
        smoothing
      );

    var svg =
      '<svg xmlns="http://www.w3.org/2000/svg" ' +
        'viewBox="0 0 ' +
        width +
        " " +
        height +
        '">' +
        '<path d="' +
        path +
        '" fill="black"/>' +
