window.jumpTo = async function (targetIndex) {
  if (openingSwitchBusy) {
    return false;
  }

  // 不把空值、布尔值等误当成索引 0。
  var validType =
    typeof targetIndex === "number" ||
    (
      typeof targetIndex === "string" &&
      targetIndex.trim() !== ""
    );

  var index = validType ? Number(targetIndex) : NaN;

  if (!Number.isInteger(index) || index < 0) {
    window.alert("这个入口还没有填写有效的开场白编号。");
    return false;
  }

  openingSwitchBusy = true;

  try {
    if (
      typeof getChatMessages !== "function" ||
      typeof setChatMessages !== "function"
    ) {
      throw new Error("当前页面无法使用酒馆助手的消息接口。");
    }

    // 读取第一条消息及其全部候选开场白。
    var messages = await getChatMessages("0", {
      include_swipes: true
    });

    var opening = Array.isArray(messages)
      ? messages[0]
      : null;

    if (!opening || !Array.isArray(opening.swipes)) {
      throw new Error("没有读取到第一条消息的候选开场白。");
    }

    var count = opening.swipes.length;

    if (index >= count) {
      window.alert(
        "找不到编号为 " + index + " 的开场白。\n" +
        (
          count > 0
            ? "当前可用编号为 0～" + (count - 1) + "。"
            : "当前没有可用的候选开场白。"
        )
      );

      return false;
    }

    if (opening.swipe_id === index) {
      return true;
    }

    // 交给酒馆助手切换候选，并刷新对应消息。
    await setChatMessages(
      [
        {
          message_id: opening.message_id,
          swipe_id: index
        }
      ],
      {
        refresh: "affected"
      }
    );

    return true;
  } catch (error) {
    console.error("[YouTube 开场白切换]", error);

    window.alert(
      "这次没有完成开场白切换。\n" +
      (
        error && error.message
          ? error.message
          : "请查看控制台中的错误信息。"
      )
    );

    return false;
  } finally {
    openingSwitchBusy = false;
  }
};

// 视频卡片只负责传入配置中的目标编号。
async function jumpVideo(video) {
  if (!video || youtubeBookmarkJumpBusy) {
    return false;
  }

  youtubeBookmarkJumpBusy = true;

  var previousBookmark = readYouTubeBookmark();

  /*
   * 切换开场白可能卸载当前 iframe，
   * 所以必须在切换之前保存。
   */
  writeYouTubeBookmark({
    swipe: video.swipe,
    title: video.title || "",
    sort: state.sort,
    videoGroup: state.videoGroup || ""
  });

  try {
    var success = await window.jumpTo(video.swipe);

    if (!success) {
      writeYouTubeBookmark(previousBookmark);
    }

    return success;
  } catch (error) {
    writeYouTubeBookmark(previousBookmark);
    console.error("[YouTube 暗号]", error);
    return false;
  } finally {
    youtubeBookmarkJumpBusy = false;
  }
}


