/* =======================================================
 * 单排按钮：最新 / 最早 / 自定义故事线
 * ======================================================= */

function renderSorts(root) {
  /* Shorts 不显示这一排 */
  if (state.tab === "shorts") {
    return;
  }

  var section = createElement(
    "section",
    "yt-sort"
  );

  section.setAttribute(
    "aria-label",
    "开场白筛选与排序"
  );

  var configuredSorts = Array.isArray(cfg.sorts)
    ? cfg.sorts
    : [
        { id: "latest", label: "最新" },
        { id: "oldest", label: "最早" }
      ];

  var options = [];

  /* 前面是“最新”“最早” */
  configuredSorts.forEach(function (sort) {
    if (
      sort &&
      (
        sort.id === "latest" ||
        sort.id === "oldest"
      )
    ) {
      options.push({
        type: "sort",
        id: sort.id,
        label: sort.label || sort.id
      });
    }
  });

  /* 故事线按钮只出现在视频 Tab */
  if (state.tab === "videos") {
    videoGroups.forEach(function (group) {
      options.push({
        type: "group",
        id: group.id,
        label: group.label
      });
    });
  }

  if (!options.length) {
    return;
  }

  options.forEach(function (option) {
    var button = createElement(
      "button",
      "yt-sort-button yt-squircle"
    );

    button.type = "button";
    button.textContent = option.label;

    button.setAttribute("data-radius", "10");
    button.setAttribute("data-smooth", "0.85");

    /*
     * 故事线筛选只在视频 Tab 生效。
     * 其他 Tab 不受保留的视频分组状态影响。
     */
    var hasActiveGroup =
      state.tab === "videos" &&
      state.videoGroup !== "";

    var active = option.type === "group"
      ? hasActiveGroup && state.videoGroup === option.id
      : !hasActiveGroup && state.sort === option.id;

    button.classList.toggle("is-active", active);

    button.setAttribute(
      "aria-pressed",
      String(active)
    );

    button.addEventListener("click", function () {
      if (active) {
        return;
      }

      /* 重建内容后保留按钮栏的横向滚动位置 */
      var previousScrollLeft = section.scrollLeft;

      if (option.type === "group") {
        /*
         * 点击故事线：
         * 只显示这一组，组内按最新排列。
         */
        state.videoGroup = option.id;
        state.sort = "latest";
      } else {
        /*
         * 点击最新 / 最早：
         * 清除故事线筛选，显示全部开场白。
         */
        state.videoGroup = "";
        state.sort = option.id;
      }

      renderTabContent();

      var content = byId("ytTabContent");

      if (content) {
        content.scrollTop = 0;

        var newSortBar = content.querySelector(
          ".yt-sort"
        );

        if (newSortBar) {
          newSortBar.scrollLeft = previousScrollLeft;
        }
      }

      refreshScale();
    });

    section.appendChild(button);
  });

  root.appendChild(section);
}

