/* =======================================================
 * 视频发布日期
 * ======================================================= */

function parseVideoPublishedDate(value) {
  var text = String(value || "").trim();

  var match = text.match(
    /^(\d{4})-(\d{2})-(\d{2})$/
  );

  if (!match) {
    return null;
  }

  var year = Number(match[1]);
  var month = Number(match[2]);
  var day = Number(match[3]);

  var date = new Date(
    year,
    month - 1,
    day
  );

  /*
   * 防止 2026-02-31 这类无效日期
   * 被 JavaScript 自动换算到下个月。
   */
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return null;
  }

  return date;
}

function getVideoDateValue(video) {
  var date = parseVideoPublishedDate(
    video && video.publishedDate
  );

  return date
    ? date.getTime()
    : null;
}

function formatVideoPublished(video) {
  /* 填了自定义文字时，优先显示；留空则自动计算日期。 */
  var customText = String(
    video && video.publishedText || ""
  ).trim();

  if (customText) {
    return customText;
  }
  /*
   * 统一换算：
   * 不满 7 天显示天数；
   * 不满 30 天显示周数；
   * 不满 365 天显示月数；
   * 365 天及以上显示年数。
   */
function formatDays(difference) {
  if (difference === 0) {
    return "今天";
  }

  var days = Math.abs(difference);
  var suffix = difference > 0 ? "前" : "后";

  if (days < 7) {
    return days + " 天" + suffix;
  }

  if (days < 30) {
    return Math.floor(days / 7) + " 周" + suffix;
  }

  if (days < 365) {
    return Math.floor(days / 30) + " 个月" + suffix;
  }

  return Math.floor(days / 365) + " 年" + suffix;
}

  var date = parseVideoPublishedDate(
    video && video.publishedDate
  );

  /*
   * 兼容旧配置：
   * “80 天前”“80天前”也会换算成“2个月前”。
   * 其他自定义文字继续按原内容显示。
   */
  if (!date) {
    var original = String(
      video && video.published || ""
    ).trim();

    var match = original.match(
      /^(\d+)\s*天\s*(前|后)$/
    );

    if (match) {
      var days = Number(match[1]);

      if (Number.isSafeInteger(days)) {
        return formatDays(
          match[2] === "前" ? days : -days
        );
      }
    }

return original.replace(
      /^(\d+)\s*(天|周|个月|年)\s*(前|后)$/,
      "$1 $2$3"
    );
  }

  var now = new Date();

  /*
   * 使用本地年月日，再换成统一的日期刻度。
   * 不受当天时分秒和夏令时切换影响。
   */
  var todayValue = Date.UTC(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()
  );

  var dateValue = Date.UTC(
    date.getFullYear(),
    date.getMonth(),
    date.getDate()
  );

  var difference = Math.round(
    (todayValue - dateValue) / 86400000
  );

  return formatDays(difference);
}

function getVisibleVideos() {
  var videos = Array.isArray(cfg.videos)
