    : [];

  /* 先筛选当前 Tab */
  if (state.tab !== "home") {
    videos = videos.filter(function (video) {
      return video.tab === state.tab;
    });
  }

  /* 只有视频 Tab 可以按故事线筛选 */
  var hasActiveGroup =
    state.tab === "videos" &&
    state.videoGroup !== "";

  if (hasActiveGroup) {
    videos = videos.filter(function (video) {
      return video.group === state.videoGroup;
    });
  }

  /*
   * 排序只按照 videos 配置区里的原始位置。
   *
   * 最新：
   * 第一条、第二条、第三条……
   *
   * 最早：
   * 最后一条、倒数第二条、倒数第三条……
   *
   * 日期、order、观看次数都不参与排序。
   */
  videos.sort(function (a, b) {
    var aIndex = Number(a._youtubeListIndex);
    var bIndex = Number(b._youtubeListIndex);

    aIndex = Number.isFinite(aIndex)
      ? aIndex
      : 0;

    bIndex = Number.isFinite(bIndex)
      ? bIndex
      : 0;

    return state.sort === "oldest"
      ? bIndex - aIndex
      : aIndex - bIndex;
  });

  return videos;
}


