function formatPostCount(value) {
  var number = Math.max(0, Math.floor(Number(value) || 0));

  if (number < 10000) {
    return String(number);
  }

  return (number / 10000).toFixed(1).replace(/\.0$/, "") + "万";
}

/* =======================================================
 * 置顶优先，然后进行时间排序
 * ======================================================= */

function getVisiblePosts() {
  var posts = Array.isArray(cfg.posts)
    ? cfg.posts.filter(function (post) {
        return post && post.id !== undefined && post.id !== null;
      })
    : [];

  function numeric(value) {
    var number = Number(value);
    return Number.isFinite(number) ? number : 0;
  }

  return posts.slice().sort(function (a, b) {
    var aPinned = a.pinned === true;
    var bPinned = b.pinned === true;

    if (aPinned !== bPinned) {
      return aPinned ? -1 : 1;
    }

    if (aPinned && bPinned) {
      return (
        numeric(a.pinOrder) - numeric(b.pinOrder) ||
        numeric(b.order) - numeric(a.order)
      );
    }

    return postState.sort === "oldest"
      ? numeric(a.order) - numeric(b.order)
      : numeric(b.order) - numeric(a.order);
  });
}

/* =======================================================
 * 正文折叠
 *
 * 在 DOM 插入后测量实际文本高度。
 * 使用未缩放的布局尺寸，不受整页 scale 影响。
 * ======================================================= */

function measurePostBody(card) {
  var body = card.querySelector(".yt-post-body");
  var more = card.querySelector(".yt-post-more");

  if (!body || !more || !body.offsetWidth) {
    return;
  }

  /*
   * 第一次测量时保存完整正文。
   * 后续截断、展开、窗口变化都从完整正文重新计算。
   */
  if (body._postFullText === undefined) {
    body._postFullText = body.textContent;
  }

  var fullText = body._postFullText;
  var expanded = card.dataset.expanded === "true";

  /* 不再使用 CSS line-clamp，由实际排版高度决定截取位置 */
  body.classList.remove("is-collapsed");
  body.textContent = fullText;

  var style = window.getComputedStyle(body);

  var lines = Math.max(
    1,
    parseInt(style.getPropertyValue("--post-lines"), 10) || 6
  );

  var lineHeight = parseFloat(style.lineHeight);
  var maxHeight = lineHeight * lines;

  /* 容许布局高度取整造成的微小误差 */
  var overflowing = body.scrollHeight > maxHeight + 1;

  more.classList.toggle("is-expanded", expanded);
  more.setAttribute("aria-expanded", String(expanded));

  /*
   * 不超过设定行数：显示完整正文，隐藏按钮。
   * 按钮仍留在 DOM，方便下次重新测量时找到。
   */
  if (!overflowing) {
    more.hidden = true;
    body.appendChild(more);
    return;
  }

  more.hidden = false;

  if (expanded) {
    more.textContent = "收起";

    /* 清除文末空白，使收起按钮接在最后一段文字后面 */
    body.textContent = fullText.trimEnd();
    body.appendChild(more);
    return;
  }

  more.textContent = "…了解详情";

  /*
   * 按字符截取，避免拆开 UTF-16 代理对。
   * 支持时进一步按字素分段，避免拆开组合 emoji。
   */
  var characters;

  if (
    typeof Intl !== "undefined" &&
    typeof Intl.Segmenter === "function"
  ) {
    var segmenter = new Intl.Segmenter("zh-CN", {
      granularity: "grapheme"
    });

    characters = Array.from(
      segmenter.segment(fullText),
      function (part) {
        return part.segment;
      }
    );
  } else {
    characters = Array.from(fullText);
  }

  function renderPrefix(count) {
    body.textContent = characters
      .slice(0, count)
      .join("")
      .trimEnd();

    /* 按钮参与正文排版，测量时也计入它占用的宽度 */
    body.appendChild(more);
  }

  /*
   * 二分查找：
   * 找到“正文片段＋了解详情”能放进 6 行的最长长度。
   */
  var low = 0;
  var high = characters.length;

  while (low < high) {
    var middle = Math.ceil((low + high) / 2);

    renderPrefix(middle);

    if (body.scrollHeight <= maxHeight + 1) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }

  renderPrefix(low);
}


function refreshPostBodies() {
  var root = byId("ytTabContent");

  if (!root) {
