  var commentBox = createElement("div", "yt-post-comments");

  if (!comments.length) {
    var empty = createElement("div", "yt-post-comment-empty");
    empty.textContent = "暂无评论";
    commentBox.appendChild(empty);
  } else {
    comments.forEach(function (comment) {
      var row = createElement("div", "yt-post-comment");
      var name = createElement("div", "yt-post-comment-author");
      var text = createElement("div", "yt-post-comment-body");

      name.textContent = comment.author || "匿名";
      text.textContent = comment.body || "";

      row.appendChild(name);
      row.appendChild(text);
      commentBox.appendChild(row);
    });
  }

  function updateComments() {
    commentBox.hidden = !local.commentsOpen;
    commentButton.setAttribute("aria-expanded", String(local.commentsOpen));
    commentButton.setAttribute(
      "aria-label",
      (local.commentsOpen ? "收起评论，" : "展开评论，") +
      comments.length +
      " 条"
    );
  }

  commentButton.addEventListener("click", function () {
    local.commentsOpen = !local.commentsOpen;
    updateComments();
    refreshScale();
  });

  updateComments();
  card.appendChild(commentBox);

  return card;
}

/* =======================================================
 * 帖子 Tab：独立排序栏＋帖子列表
 * ======================================================= */

function renderPosts(root) {
  var sortBar = createElement("section", "yt-sort");
  sortBar.setAttribute("aria-label", "帖子排序");

  [
    { id: "latest", label: "最新" },
    { id: "oldest", label: "最早" }
  ].forEach(function (option) {
    var button = createElement(
      "button",
      "yt-sort-button yt-squircle"
    );

    button.type = "button";
    button.textContent = option.label;
    button.setAttribute("data-radius", "10");
    button.setAttribute("data-smooth", "0.85");

    var active = postState.sort === option.id;

    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", String(active));

    button.addEventListener("click", function () {
      if (postState.sort === option.id) {
        return;
      }

      postState.sort = option.id;

      renderTabContent();
      root.scrollTop = 0;

      /* 重建排序栏后恢复键盘焦点 */
      var buttons = root.querySelectorAll(".yt-sort-button");
      var index = option.id === "latest" ? 0 : 1;

      if (buttons[index]) {
        buttons[index].focus({ preventScroll: true });
      }

      refreshScale();
    });

    sortBar.appendChild(button);
  });

  root.appendChild(sortBar);

  var list = createElement("section", "yt-posts");
  var posts = getVisiblePosts();

  if (!posts.length) {
    var empty = createElement("div", "yt-empty");
    empty.textContent = "这里暂时没有帖子";
    list.appendChild(empty);
  } else {
    posts.forEach(function (post) {
      list.appendChild(createPostElement(post));
    });
  }

  root.appendChild(list);
  schedulePostBodyRefresh();
}

