/* =======================================================
 * 首图自动取色
 *
 * 显示图片与取色图片分开加载：
 * 即使图床不允许读取像素，也不影响首图正常显示。
 * 同一张图的取色结果会在本次页面内缓存。
 * ======================================================= */

var playlistColorCache = new Map();

function parsePlaylistColor(value) {
  var hex = String(value || "").trim();

  if (/^#[0-9a-f]{3}$/i.test(hex)) {
    hex =
      "#" +
      hex[1] + hex[1] +
      hex[2] + hex[2] +
      hex[3] + hex[3];
  }

  if (!/^#[0-9a-f]{6}$/i.test(hex)) {
    hex = "#c9c1b5";
  }

  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16)
  ];
}

function mixPlaylistColor(rgb, target, amount) {
  return rgb.map(function (channel, index) {
    return Math.round(
      channel * (1 - amount) +
      target[index] * amount
    );
  });
}

function playlistRgb(rgb) {
  return "rgb(" + rgb.join(", ") + ")";
}

function paintPlaylistPalette(element, rgb) {
  var white = [255, 255, 255];

  /* 轻微降低饱和度，避免叠层颜色过于鲜艳 */
  var average = Math.round(
    (rgb[0] + rgb[1] + rgb[2]) / 3
  );

  var softened = mixPlaylistColor(
    rgb,
    [average, average, average],
    0.16
  );

  element.style.setProperty(
    "--pl-front",
    playlistRgb(mixPlaylistColor(softened, white, 0.30))
  );

  element.style.setProperty(
    "--pl-back",
    playlistRgb(mixPlaylistColor(softened, white, 0.62))
  );

  element.style.setProperty(
    "--pl-soft",
    playlistRgb(mixPlaylistColor(softened, white, 0.82))
  );

  element.style.setProperty(
    "--pl-ink",
    playlistRgb(softened)
  );
}

function extractPlaylistColor(source) {
  if (playlistColorCache.has(source)) {
    return playlistColorCache.get(source);
  }

  var task = new Promise(function (resolve) {
    var image = new Image();
    var finished = false;
    var timer;

    function finish(result) {
      if (finished) {
        return;
      }

      finished = true;
      window.clearTimeout(timer);
      image.onload = null;
      image.onerror = null;
      resolve(result);
    }

    timer = window.setTimeout(function () {
      finish(null);
    }, 8000);

    image.crossOrigin = "anonymous";

    image.onerror = function () {
      finish(null);
    };

    image.onload = function () {
      try {
        var canvas = document.createElement("canvas");
        canvas.width = 48;
        canvas.height = 48;

        var context = canvas.getContext("2d", {
          willReadFrequently: true
        });

        if (!context) {
          finish(null);
          return;
        }

        context.drawImage(image, 0, 0, 48, 48);

        var pixels = context.getImageData(
          0, 0, 48, 48
        ).data;

        var buckets = Object.create(null);
        var totals = [0, 0, 0];
        var totalCount = 0;

        for (var i = 0; i < pixels.length; i += 4) {
          if (pixels[i + 3] < 128) {
            continue;
          }

          var r = pixels[i];
          var g = pixels[i + 1];
          var b = pixels[i + 2];

          totals[0] += r;
          totals[1] += g;
          totals[2] += b;
          totalCount += 1;

          var maximum = Math.max(r, g, b);
          var minimum = Math.min(r, g, b);
          var lightness = (maximum + minimum) / 2;

          /* 过滤接近纯白和纯黑的区域 */
          if (lightness > 242 || lightness < 24) {
            continue;
          }

          var saturation = maximum
            ? (maximum - minimum) / maximum
            : 0;

          var key =
            Math.floor(r / 32) + "," +
            Math.floor(g / 32) + "," +
            Math.floor(b / 32);

          if (!buckets[key]) {
            buckets[key] = {
              score: 0,
              count: 0,
              rgb: [0, 0, 0]
            };
          }

          var bucket = buckets[key];

          /* 兼顾面积与色彩，稍微优先有颜色的区域 */
          bucket.score += 1 + saturation * 2;
          bucket.count += 1;
          bucket.rgb[0] += r;
          bucket.rgb[1] += g;
          bucket.rgb[2] += b;
        }

        var best = null;

        Object.keys(buckets).forEach(function (key) {
          var bucket = buckets[key];

          if (!best || bucket.score > best.score) {
            best = bucket;
          }
        });

        if (best) {
          finish(best.rgb.map(function (value) {
            return Math.round(value / best.count);
          }));
          return;
        }

        /* 黑白图片等情况，使用平均颜色 */
        if (totalCount) {
          finish(totals.map(function (value) {
            return Math.round(value / totalCount);
          }));
          return;
        }

        finish(null);
      } catch (error) {
        /* 跨域读取失败时保留备用色 */
        finish(null);
      }
    };

    image.src = source;
  });

  playlistColorCache.set(source, task);
  return task;
}

function applyPlaylistPalette(element, playlist) {
  /* 先应用备用色，图片读取完成后再更新 */
  paintPlaylistPalette(
    element,
    parsePlaylistColor(playlist.color)
  );

  var source = typeof playlist.cover === "string"
    ? playlist.cover.trim()
    : "";

  if (!source || playlist.autoColor === false) {
    return;
  }

  extractPlaylistColor(source).then(function (rgb) {
    if (rgb && element.isConnected) {
      paintPlaylistPalette(element, rgb);
    }
  });
}

/* =======================================================
 * 播放列表：共用元素
 * ======================================================= */

function playlistText(tag, className, value) {
  var node = createElement(tag, className);

  node.textContent =
    value === undefined || value === null
      ? ""
      : String(value);

  return node;
}

function getPlaylistEntries(playlist) {
  return Array.isArray(playlist.entries)
    ? playlist.entries.filter(function (entry) {
        return entry && typeof entry === "object";
      })
    : [];
}

function createPlaylistBadge(count) {
var badge = createElement(
  "span",
  "yt-pl-badge yt-squircle"
);

badge.setAttribute("data-radius", "999");
badge.setAttribute("data-smooth", "0.7");

  badge.appendChild(createPlaylistIcon());

  badge.appendChild(
    playlistText("span", "", count + " 条")
  );

  return badge;
}

function createPlaylistCover(playlist, index, isHero) {
  var cover = createElement(
    "div",
    isHero
      ? "yt-pl-hero-cover"
      : "yt-pl-cover yt-squircle"
  );

  /*
   * 列表封面使用连续曲率圆角。
   * 详情图片由整张 hero 卡片统一裁切，
   * 图片底部与文字区域自然连接。
   */
  if (!isHero) {
    cover.setAttribute("data-radius", "8");
    cover.setAttribute("data-smooth", "0.7");
  }

  var number = playlistText(
    "span",
    "yt-pl-number",
    String(index + 1).padStart(2, "0")
  );

  number.setAttribute("aria-hidden", "true");
  cover.appendChild(number);

  var source = typeof playlist.cover === "string"
    ? playlist.cover.trim()
    : "";

  if (source) {
    var image = createElement("img");

    image.alt = "";
    image.draggable = false;
    image.decoding = "async";

    image.addEventListener("load", function () {
      number.hidden = true;
    });

    image.addEventListener("error", function () {
      image.remove();
      number.hidden = false;
    });

    image.src = source;
    cover.appendChild(image);
  }

  /* 只有列表首页的小封面显示数量胶囊 */
  if (!isHero) {
    cover.appendChild(
      createPlaylistBadge(
        getPlaylistEntries(playlist).length
      )
    );
  }

  return cover;
}


/* =======================================================
 * 播放列表 Tab
 *
 * 使用原来的 ytTabContent 滚动容器。
 * 进入详情、返回列表时不会滚动整个宿主页面。
 * ======================================================= */

function renderPlaylists(root) {
  var playlists = Array.isArray(cfg.playlists)
    ? cfg.playlists.filter(function (playlist) {
        return playlist && typeof playlist === "object";
      })
    : [];

  var shell = createElement("section", "yt-pl-root");
  shell.setAttribute("aria-label", "播放列表");

  var listView = createElement("div", "yt-pl-list");
  var detailView = createElement("div", "yt-pl-detail");
  detailView.hidden = true;

  shell.appendChild(listView);
  shell.appendChild(detailView);
  root.appendChild(shell);

  var previousButton = null;
  var previousScroll = 0;

  function returnToList() {
    detailView.hidden = true;
    listView.hidden = false;

    if (previousButton && previousButton.isConnected) {
      previousButton.focus({ preventScroll: true });
    }

    root.scrollTop = previousScroll;
    refreshScale();
  }

  function openPlaylist(playlist, index, trigger) {
    previousButton = trigger;
    previousScroll = root.scrollTop;

    listView.hidden = true;
    detailView.hidden = false;
    detailView.replaceChildren();

    applyPlaylistPalette(detailView, playlist);

    /* 返回按钮 */
    var back = createElement("button", "yt-pl-back");
    back.type = "button";

    back.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" ' +
        'stroke="currentColor" stroke-width="2" ' +
        'stroke-linecap="round" stroke-linejoin="round" ' +
        'aria-hidden="true" focusable="false">' +
        '<path d="m14 6-6 6 6 6"/>' +
      '</svg>';

    back.appendChild(
      playlistText("span", "", "所有播放列表")
    );

    back.addEventListener("click", returnToList);
    detailView.appendChild(back);

    /* 详情首图：与列表封面共用 playlist.cover */
var hero = createElement(
  "div",
  "yt-pl-hero yt-squircle"
);

hero.setAttribute("data-radius", "12");
hero.setAttribute("data-smooth", "0.7");

    hero.appendChild(
      createPlaylistCover(playlist, index, true)
    );

    var heroText = createElement("div", "yt-pl-hero-text");

    var heading = playlistText(
      "h2",
      "yt-pl-hero-title",
      playlist.title || "未命名列表"
    );

    var entries = getPlaylistEntries(playlist);

    var meta = playlistText(
      "div",
      "yt-pl-hero-meta",
      (cfg.name || "作者") + " · " + entries.length + " 条资料"
    );

    /* 左侧播放列表图标 */
var heroIcon = createElement(
  "div",
  "yt-pl-hero-icon"
);

heroIcon.setAttribute("aria-hidden", "true");
heroIcon.appendChild(createPlaylistIcon());

/* 右侧标题与署名 */
var heroCopy = createElement(
  "div",
  "yt-pl-hero-copy"
);

heroCopy.appendChild(heading);
heroCopy.appendChild(meta);

heroText.appendChild(heroIcon);
heroText.appendChild(heroCopy);

hero.appendChild(heroText);
    detailView.appendChild(hero);

    /* 只保留展开控制，不生成排序按钮 */
    var tools = createElement("div", "yt-pl-tools");
    var expand = playlistText(
  "button",
  "yt-pl-expand yt-squircle",
  "全部展开"
);

expand.setAttribute("data-radius", "999");
expand.setAttribute("data-smooth", "0.7");

expand.type = "button";

    expand.disabled = entries.length === 0;

    tools.appendChild(expand);
    detailView.appendChild(tools);

    var entriesRoot = createElement("div", "yt-pl-entries");
    var detailsNodes = [];

    function updateExpandButton() {
      var allOpen =
        detailsNodes.length > 0 &&
        detailsNodes.every(function (node) {
          return node.open;
        });

      expand.textContent = allOpen
        ? "全部收起"
        : "全部展开";
    }

    entries.forEach(function (entry, entryIndex) {
      var details = createElement("details", "yt-pl-entry");
      var summary = document.createElement("summary");

      summary.appendChild(
        playlistText(
          "span",
          "yt-pl-entry-number",
          String(entryIndex + 1).padStart(2, "0")
        )
      );

      summary.appendChild(
        playlistText(
          "span",
          "yt-pl-entry-title",
          entry.title || "未命名条目"
        )
      );

      var arrowHolder = document.createElement("div");

      arrowHolder.innerHTML =
        '<svg class="yt-pl-chevron" ' +
          'viewBox="0 0 24 24" fill="none" ' +
          'stroke="currentColor" stroke-width="1.8" ' +
          'stroke-linecap="round" stroke-linejoin="round" ' +
          'aria-hidden="true" focusable="false">' +
          '<path d="m6 9 6 6 6-6"/>' +
        '</svg>';

      summary.appendChild(arrowHolder.firstElementChild);

      var answer = createElement("div", "yt-pl-answer");

      answer.appendChild(
        playlistText(
          "div",
          "yt-pl-answer-author",
          entry.author || cfg.name || "作者"
        )
      );

      answer.appendChild(
        playlistText(
          "div",
          "yt-pl-answer-text",
          entry.body || ""
        )
      );

      details.appendChild(summary);
      details.appendChild(answer);

      details.addEventListener("toggle", function () {
        updateExpandButton();
        refreshScale();
      });

      detailsNodes.push(details);
      entriesRoot.appendChild(details);
    });

    if (!entries.length) {
      entriesRoot.appendChild(
        playlistText("div", "yt-empty", "这个列表暂时没有内容")
      );
    }

    expand.addEventListener("click", function () {
      var shouldOpen = !detailsNodes.every(function (node) {
        return node.open;
      });

      detailsNodes.forEach(function (node) {
        node.open = shouldOpen;
      });

      updateExpandButton();
      refreshScale();
    });

    detailView.appendChild(entriesRoot);
    updateExpandButton();

    back.focus({ preventScroll: true });
    root.scrollTop = 0;
    refreshScale();
  }

  if (!playlists.length) {
    listView.appendChild(
      playlistText("div", "yt-empty", "这里暂时没有播放列表")
    );
    return;
  }

  playlists.forEach(function (playlist, index) {
    var card = createElement("button", "yt-pl-card");
    card.type = "button";

    card.setAttribute(
      "aria-label",
      "查看播放列表：" + (playlist.title || "未命名列表")
    );

var stack = createElement("div", "yt-pl-stack");

/* 最后面的一层 */
var backLayer = createElement(
  "span",
  "yt-pl-stack-layer yt-pl-stack-layer--back yt-squircle"
);

backLayer.setAttribute("aria-hidden", "true");
backLayer.setAttribute("data-radius", "7");
backLayer.setAttribute("data-smooth", "0.7");

/* 中间的一层 */
var frontLayer = createElement(
  "span",
  "yt-pl-stack-layer yt-pl-stack-layer--front yt-squircle"
);

frontLayer.setAttribute("aria-hidden", "true");
frontLayer.setAttribute("data-radius", "7");
frontLayer.setAttribute("data-smooth", "0.7");

stack.appendChild(backLayer);
stack.appendChild(frontLayer);

stack.appendChild(
  createPlaylistCover(playlist, index, false)
);

    var info = createElement("div", "yt-pl-info");

    info.appendChild(
      playlistText(
        "div",
        "yt-pl-title",
        playlist.title || "未命名列表"
      )
    );

    info.appendChild(
      playlistText(
        "div",
        "yt-pl-author",
        cfg.name || "作者"
      )
    );

    card.appendChild(stack);
    card.appendChild(info);

    card.addEventListener("click", function () {
      openPlaylist(playlist, index, card);
    });

    listView.appendChild(card);
    applyPlaylistPalette(card, playlist);
  });
}

/* =======================================================
 * 当前 Tab 内容
 * ======================================================= */

function renderTabContent() {
  var root = byId("ytTabContent");

  if (!root) {
    return;
  }

  root.replaceChildren();

  if (state.tab === "home") {
    root.appendChild(renderHome());

  } else if (state.tab === "post") {
    renderPosts(root);

  } else if (state.tab === "shorts") {
    /* 保留旧内部标识，显示新的播放列表 */
    renderPlaylists(root);

  } else {
    renderVideos(root);
  }

  scheduleSquircleRefresh();
}


/* =======================================================
 * 致谢弹窗：优先在最外层可访问文档中显示
 * ======================================================= */

var thanksModalElement =
  document.getElementById("ytThanksModal");

var thanksHostWindow = window;
var thanksHostDocument = document;
var thanksPortalStyle = null;

var thanksPreviousFocus = null;
var thanksBackground = byId("ytScaleSpace");
var thanksBackgroundWasInert = false;

var thanksSavedBodyOverflow = "";
var thanksSavedHtmlOverflow = "";

function applyThanksConfig() {
  if (!thanksModalElement) {
    return;
  }

  var settings =
    cfg.thanks &&
    cfg.thanks.settings
      ? cfg.thanks.settings
      : {};

  var styles = {
    "--thanks-card-width": settings.cardWidth,
    "--thanks-card-padding-top":
      settings.cardPaddingTop,
    "--thanks-card-padding-bottom":
      settings.cardPaddingBottom,

    "--thanks-backdrop-blur":
      settings.backdropBlur,
    "--thanks-backdrop-saturate":
      settings.backdropSaturate,
    "--thanks-backdrop-color":
      settings.backdropColor,

    "--thanks-avatar-size":
      settings.avatarSize,

    "--thanks-wing-width":
      settings.wingWidth,
    "--thanks-wing-gap":
      settings.wingGap,
    "--thanks-wing-y":
      settings.wingY,

    "--thanks-name-size":
      settings.nameSize,
    "--thanks-quote-size":
      settings.quoteSize,
    "--thanks-quote-mark-size":
      settings.quoteMarkSize,

    "--thanks-header-image":
      settings.headerImage
        ? 'url("' + settings.headerImage + '")'
        : "none",

    "--thanks-header-image-opacity":
      settings.headerImageOpacity,
    "--thanks-header-image-position":
      settings.headerImagePosition,
    "--thanks-header-fade-start":
      settings.headerFadeStart,
    "--thanks-header-bottom":
      settings.headerBottom,

    "--thanks-close-size":
      settings.closeSize,
    "--thanks-close-color":
      settings.closeColor,
    "--thanks-close-stroke-width":
      settings.closeStrokeWidth
  };

  Object.keys(styles).forEach(function (property) {
    var value = styles[property];

    if (
      value !== undefined &&
      value !== null &&
      value !== ""
    ) {
      thanksModalElement.style.setProperty(
        property,
        String(value)
      );
    }
  });

  if (settings.wingImage) {
    var wings =
      thanksModalElement.querySelectorAll(
        ".yt-thanks-wing"
      );

