function collectThanksStyles(rules) {
  var result = "";

  Array.prototype.forEach.call(rules, function (rule) {
    if (rule.selectorText) {
      var selectors = rule.selectorText
        .split(",")
        .filter(function (selector) {
          return selector.trim().indexOf(".yt-thanks-") === 0;
        });

      if (selectors.length) {
        result +=
          selectors.join(",") +
          "{" + rule.style.cssText + "}\n";
      }

      return;
    }

    /* 弹窗入场动画 */
    if (rule.name === "ytThanksDialogIn") {
      result += rule.cssText + "\n";
      return;
    }

    /* 保留 prefers-reduced-motion 等媒体查询 */
    if (rule.type === 4 && rule.cssRules) {
      var nested = collectThanksStyles(rule.cssRules);

      if (nested) {
        result +=
          "@media " + rule.conditionText +
          "{" + nested + "}\n";
      }
