/*
 * 将视频列表的可见区域放到酒馆聊天窗口中央。
 * 如果列表比聊天窗口还高，则对齐顶部，留出 12px。
 */
function revealYouTubeVideoArea(content) {
  if (!content || !content.isConnected) {
    return;
  }

  var rect = content.getBoundingClientRect();

  /* 当前窗口坐标，已经包含 YouTube 自身的缩放 */
  var areaTop = rect.top;
  var areaHeight = rect.height;
  var current = window;

  try {
    while (current.parent !== current) {
      var frame = current.frameElement;
      var parentHost = current.parent;

      void parentHost.document.documentElement;

      if (!frame) {
        return;
      }

      var frameRect = frame.getBoundingClientRect();

      var frameScale = frame.offsetHeight
        ? frameRect.height / frame.offsetHeight
        : 1;

      if (!Number.isFinite(frameScale) || frameScale <= 0) {
        frameScale = 1;
      }

      /* 换算到父窗口坐标 */
      areaTop =
        frameRect.top +
        (frame.clientTop + areaTop) * frameScale;

      areaHeight *= frameScale;

      var chat = frame.closest("#chat");

      if (chat) {
        var chatRect = chat.getBoundingClientRect();

        var chatScale = chat.offsetHeight
          ? chatRect.height / chat.offsetHeight
          : 1;

        if (!Number.isFinite(chatScale) || chatScale <= 0) {
          chatScale = 1;
        }

        var visibleTop =
          chatRect.top + chat.clientTop * chatScale;

        var visibleHeight = chat.clientHeight * chatScale;

        /*
         * 放得下：上下居中。
         * 放不下：顶部保留 12px，让目标视频先露出来。
         */
        var inset = Math.max(
          12,
          (visibleHeight - areaHeight) / 2
        );

        var destination =
          chat.scrollTop +
          (areaTop - visibleTop - inset) / chatScale;

        var maximum = Math.max(
          0,
          chat.scrollHeight - chat.clientHeight
        );

        chat.scrollTo({
          top: Math.max(0, Math.min(maximum, destination)),
          behavior: "instant"
        });

        return;
      }

      current = parentHost;
    }
  } catch (error) {
    console.warn("[YouTube 外层定位]", error);
  }
}


async function restoreYouTubeVideoPosition() {
